import styled from '@emotion/styled';

interface StyledBrandPowerBigNumbersProps {
  $isYtd?: boolean;
}

export const StyledBrandPowerBigNumbers = styled.div<StyledBrandPowerBigNumbersProps>(
  ({ $isYtd }) => ({
    display: 'flex',
    gap: '16px',
    height: '100%',
    width: '100%',

    ...($isYtd === true && {
      '& .brand-power-big-number-ytd.bigNumberCard': {
        height: '100%',
      },
      '& .brand-power-big-number-ytd.bigNumberContainer': {
        height: '100%',
      },
      '& .brand-power-big-number-ytd.bigNumberContainer > div:last-child': {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flex: 1,
        height: 'auto',
      },
    }),
  }),
);
